INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q12717499', 'Siege of Colonia del Sacramento', 'The siege of Colonia del Sacramento was a successful siege in 1704 by Spanish forces of the Portuguese colonial town of Colonia del Sacramento, opposite Buenos Aires and now in the nation of Uruguay. Four thousand natives and 650 Spaniards, led by the governor of Buenos Aires, Don Alonso Juan de Valdes e Inclán, and Baltasar García Ros, besieged the city beginning late in 1704.', 1704, 12, NULL, 1705, 2, NULL, 'month', 'December 1704 – February 1705', 37, 'https://en.wikipedia.org/wiki/Siege_of_Colonia_del_Sacramento'),
  ('Q2358507', 'First Cevallos expedition', 'The First Cevallos expedition was a series of Spanish military operations in South America during the Fantastic War. Under the command of the governor of Buenos Aires, Pedro de Cevallos, the expedition captured the Portuguese settlement of Colónia do Sacramento and fought off a joint Anglo-Portuguese attempt to recapture it.', 1762, 9, NULL, 1763, 4, NULL, 'month', 'September 1762 – April 1763', 43, 'https://en.wikipedia.org/wiki/First_Cevallos_expedition'),
  ('Q2889112', 'Battle of Las Piedras', 'The Battle of Las Piedras was fought on May 18, 1811 as part of the Rio de la Plata war of independence. It was a resounding victory for the revolutionary forces, led by José Gervasio Artigas.', 1811, 5, 18, 1811, 5, 18, 'day', '18 May 1811', 47, 'https://en.wikipedia.org/wiki/Battle_of_Las_Piedras_(1811)'),
  ('Q6130113', 'Siege of Montevideo', 'The first siege of Montevideo (Spanish: primer sitio de Montevideo) took place between May and October 1811, when the troops of the United Provinces of the Río de la Plata unsuccessfully besieged the city of Montevideo, still held by Spanish loyalists. In 1810, the May Revolution had forced the Spanish to abandon Buenos Aires, but they held on to the Banda Oriental (present-day Uruguay), as Francisco Javier de Elío moved the headquarters of his Viceroyalty of the Río de la Plata to Montevideo.', 1811, NULL, NULL, 1811, 10, 12, 'year', '1811', 34, 'https://en.wikipedia.org/wiki/Siege_of_Montevideo_(1811)'),
  ('Q4870695', 'Battle of Cerrito', 'The Battle of Cerrito (outskirts of Montevideo, 31 December 1812), was a battle for the War of Independence of the Viceroyalty of the Río de la Plata, between the royalist forces who had control of the city of Montevideo and the rebel forces of the government of Buenos Aires.', 1812, 12, 31, NULL, NULL, NULL, 'day', '31 December 1812', 37, 'https://en.wikipedia.org/wiki/Battle_of_Cerrito'),
  ('Q6130115', 'Siege of Montevideo', 'The event known as the second siege of Montevideo (Spanish: Segundo Sitio de Montevideo) took place between 1812 and 1814, when the patriotic troops led by José Rondeau besieged the city of Montevideo, still held by Spanish loyalists under the leadership of Gaspar de Vigodet, governor of Montevideo. The siege was successful and marked the end of the Spanish presence in present-day Uruguay.', 1812, NULL, NULL, 1814, 6, 23, 'year', '1812 – 23 June 1814', 34, 'https://en.wikipedia.org/wiki/Siege_of_Montevideo_(1812%E2%80%931814)'),
  ('Q2890940', 'Battle of Buceo', 'The Battle of Buceo was a decisive naval battle which took place on 14–17 May 1814, during the Argentine War of Independence between an Argentine fleet under Irish-born naval commander William Brown and a Spanish fleet under Admiral Sierra off the coast of Montevideo, in today''s Uruguay.', 1814, 5, 17, NULL, NULL, NULL, 'day', '17 May 1814', 37, 'https://en.wikipedia.org/wiki/Battle_of_Buceo'),
  ('Q2356791', 'Portuguese Conquest of the Banda Oriental', 'The Portuguese conquest of the Banda Oriental, known in the Spanish-speaking world as the Luso-Brazilian invasion (Spanish: Invasión lusobrasileña) and in the Portuguese-speaking world as the War against Artigas (Portuguese: Guerra contra Artigas), was the armed-conflict that took place between 1816 and 1820 in the Banda Oriental, for control of what today comprises the whole of the Republic of Uruguay, the northern part of the Argentine Mesopotamia and southern Brazil. The four-year armed-conflict resulted in the annexation of the Banda Oriental into the United Kingdom of Portugal, Brazil…', 1816, NULL, NULL, 1820, 3, 3, 'year', '1816 – 3 March 1820', 45, 'https://en.wikipedia.org/wiki/Portuguese_conquest_of_the_Banda_Oriental'),
  ('Q2887992', 'Battle of India Muerta', 'The Battle of India Muerta took place between the Luso-Brazilian forces under the command of Sebastião Pinto de Araújo Correia against the artiguists led by Fructuoso Rivera in Rocha, present-day Uruguay. The battle lasted for four and a half hours and ended in a Luso-Brazilian victory.', 1816, 11, 18, NULL, NULL, NULL, 'day', '18 November 1816', 37, 'https://en.wikipedia.org/wiki/Battle_of_India_Muerta'),
  ('Q166218', 'Battle of Tacuarembó', 'The Battle of Tacuarembó took place between the Luso-Brazilian forces under José de Castelo Branco Correia, the Count of Figueira, and the Artiguist forces of Andrés Felipe Latorre near Tacuarembó, modern-day Uruguay. The encounter resulted in a catastrophe for the Artiguist army.', 1820, 1, 22, NULL, NULL, NULL, 'day', '22 January 1820', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tacuaremb%C3%B3'),
  ('Q2387020', 'Battle of Sarandí', 'The Battle of Sarandí was fought on 12 October 1825, in the vicinity of the Arroyo Sarandí in Uruguay, between troops of the Banda Oriental (now Uruguay) and the Empire of Brazil. It resulted in a decisive victory for the Orientals.', 1825, 10, 12, NULL, NULL, NULL, 'day', '12 October 1825', 39, 'https://en.wikipedia.org/wiki/Battle_of_Sarand%C3%AD'),
  ('Q2984801', 'Batalha de Aquila/Arbolito', 'The naval Battle of Juncal took place between a squadron of the newly independent United Provinces of the River Plate under command of William Brown and a squadron belonging to the Brazilian Empire, commanded by Sena Pereira. It spanned two days, from 8 to 9 February 1827, in the waters of the Río de la Plata.', 1827, 2, 8, 1827, 2, 9, 'day', '8 February 1827 – 9 February 1827', 41, 'https://en.wikipedia.org/wiki/Battle_of_Juncal'),
  ('Q3529812', 'Battle of Carpintería', 'The Battle of Carpintería was an important battle between troops loyal to the government of Manuel Oribe and the revolutionary forces led by Fructuoso Rivera. The combattants differentiated themselves with white or red-colored insignias.', 1836, 9, 19, NULL, NULL, NULL, 'day', '19 September 1836', 34, 'https://en.wikipedia.org/wiki/Battle_of_Carpinter%C3%ADa'),
  ('Q2672972', 'Uruguayan Civil War', 'The Uruguayan Civil War, also known in Spanish as the Guerra Grande ("Great War"), was a series of armed conflicts between the leaders of Uruguayan independence. While officially the war lasted from 1839 until 1851, it was a part of armed conflicts that started in 1832 and continued until the final military defeat of the Blancos faction in 1904.', 1839, 3, 10, 1851, 10, 8, 'day', '10 March 1839 – 8 October 1851', 62, 'https://en.wikipedia.org/wiki/Uruguayan_Civil_War'),
  ('Q6130117', 'Great Siege of Montevideo', 'The Great Siege of Montevideo (Spanish: Gran Sitio de Montevideo), named as Sitio Grande in Uruguayan historiography, was the siege suffered by the city of Montevideo between 1843 and 1851 during the Uruguayan Civil War. In practice, this siege meant that Uruguay had two parallel governments: Gobierno de la Defensa in Montevideo, led by Joaquín Suárez (1843 – 1852) Gobierno del Cerrito (with headquarters in the present-day neighborhood of Cerrito de la Victoria), ruling the rest of the country, led by Manuel Oribe (1843 – 1851) The siege inspired a book by the French writer Alexandre Dumas,…', 1843, 8, NULL, 1851, 10, 8, 'month', 'August 1843 – 8 October 1851', 47, 'https://en.wikipedia.org/wiki/Great_Siege_of_Montevideo'),
  ('Q3042457', 'Platine War', 'The Platine War (Spanish: Guerra Platina, Portuguese: Guerra do Prata, Guerra contra Oribe e Rosas; 18 August 1851 – 3 February 1852) was fought between the Argentine Confederation and an alliance consisting of the Empire of Brazil, Uruguay, and the Argentine provinces of Entre Ríos and Corrientes, with the participation of the Republic of Paraguay as Brazil''s co-belligerent and ally. The war was part of a decades-long dispute between Argentina and Brazil for influence over Uruguay and Paraguay, and hegemony over the Platine region (areas bordering the Río de la Plata).', 1851, 8, 18, 1852, 2, 3, 'day', '18 August 1851 – 3 February 1852', 53, 'https://en.wikipedia.org/wiki/Platine_War'),
  ('Q58947', 'Paraguayan War', 'The Paraguayan War, also known as the War of the Triple Alliance, was a war in South America that lasted from 1864 to 1870. It was fought between Paraguay and the Triple Alliance of Argentina, Brazil and Uruguay.', 1864, 10, 12, 1870, 3, 1, 'day', '12 October 1864 – 1 March 1870', 78, 'https://en.wikipedia.org/wiki/Paraguayan_War'),
  ('Q3042463', 'Uruguayan War', 'The Uruguayan War (10 August 1864 – 20 February 1865) was fought between Uruguay''s governing Blanco Party and an alliance consisting of the Empire of Brazil and the Uruguayan Colorado Party, covertly supported by Argentina. Since its independence, Uruguay had been ravaged by intermittent struggles between the Colorado and Blanco factions, each attempting to seize and maintain power in turn.', 1864, 8, 10, 1865, 2, 20, 'day', '10 August 1864 – 20 February 1865', 53, 'https://en.wikipedia.org/wiki/Uruguayan_War'),
  ('Q3820712', 'Siege of Paysandú', 'The Siege of Paysandú began on 3 December 1864, during the Uruguayan War, when Brazilian forces (under the Marquis of Tamandaré) and Colorado forces (under Venancio Flores) attempted to capture the city of Paysandú in Uruguay from its Uruguayan Army defenders. The siege ended on 2 January 1865, when the Brazilian and Colorado forces conquered the town.', 1864, 12, 3, 1865, 1, 2, 'day', '3 December 1864 – 2 January 1865', 39, 'https://en.wikipedia.org/wiki/Siege_of_Paysand%C3%BA'),
  ('Q6065903', 'Siege of Curupaiti', 'The passage of Curupayty was an allied naval operation carried out on 15 August 1867, in the context of the Paraguayan War, which aimed to force the passage of Brazilian battleships against the defensive fortifications installed in the Curupayty fort on the banks of the Paraguay river. There was a second crossing on 13 February 1868 with a fleet of armored monitors destined to join the fleet that had crossed first to form the squadron responsible for forcing the Passage of Humaitá.', 1867, 8, 15, NULL, NULL, NULL, 'day', '15 August 1867', 34, 'https://en.wikipedia.org/wiki/Passage_of_Curupayty_(1867)'),
  ('Q5722546', 'Battle of Lomas Valentinas', 'The Battle of Lomas Valentinas (also known as the Battle of Itá Ybaté) was fought in the Central Department of Paraguay on December 21–27, 1868. The Paraguayan Army, led personally by president Francisco Solano López, was decisively defeated, though López managed to escape.', 1868, NULL, NULL, 1868, 12, 27, 'year', '1868', 41, 'https://en.wikipedia.org/wiki/Battle_of_Lomas_Valentinas'),
  ('Q634483', '1888 Río de la Plata earthquake', 'The 1888 Río de la Plata earthquake occurred on 5 June measuring 5.5 on the Richter scale, and shook the upper Río de la Plata at 3:20 UTC-3. The epicentre was located 15 kilometres (9 mi) southwest of Colonia del Sacramento (Uruguay) and 42 kilometres (26 mi) east of Buenos Aires (Argentina), with a hypocentre at a depth of 30 kilometres (19 mi).', 1888, 6, 5, NULL, NULL, NULL, 'day', '5 June 1888', 37, 'https://en.wikipedia.org/wiki/1888_R%C3%ADo_de_la_Plata_earthquake'),
  ('Q5408962', 'Uruguayan revolution of 1897', 'The Revolution of 1897 was an uprising led by the army of the Uruguayan National Party against the government of President Juan Idiarte Borda. It took place in Uruguayan territory between March 5 and September 18, 1897.', 1897, NULL, NULL, NULL, NULL, NULL, 'year', '1897', 26, 'https://en.wikipedia.org/wiki/Revolution_of_1897'),
  ('Q492464', 'Battle of Masoller', 'The Battle of Masoller, which occurred on 1 September 1904, was the final battle of the Aparicio Saravia revolt, resulting in the victory of the Colorado forces.', 1904, 9, 1, NULL, NULL, NULL, 'day', '1 September 1904', 37, 'https://en.wikipedia.org/wiki/Battle_of_Masoller'),
  ('Q6107175', 'Uruguayan revolution of 1904', 'The Revolution of 1904 was a civic-military revolt led by Aparicio Saravia against the government of President José Batlle y Ordóñez in Uruguay. It was the last military conflict between Blancos and Colorados.', 1904, NULL, NULL, NULL, NULL, NULL, 'year', '1904', 30, 'https://en.wikipedia.org/wiki/Revolution_of_1904'),
  ('Q210862', 'Montevideo Convention', 'The Montevideo Convention on the Rights and Duties of States is a treaty signed at Montevideo, Uruguay, on December 26, 1933, during the Seventh International Conference of American States. At the conference, United States President Franklin D. Roosevelt and Secretary of State Cordell Hull declared the Good Neighbor Policy, which opposed U.S. armed intervention in the domestic affairs of Latin America.', 1933, 12, 26, NULL, NULL, NULL, 'day', '26 December 1933', 67, 'https://en.wikipedia.org/wiki/Montevideo_Convention'),
  ('Q23035649', 'Convention on the Nationality of Women', 'Convention on the Nationality of Women was the first international treaty ever adopted concerning women''s rights. It was adopted in 1933 by the Pan American Union in Montevideo, Uruguay.', 1933, NULL, NULL, NULL, NULL, NULL, 'year', '1933', 30, 'https://en.wikipedia.org/wiki/Convention_on_the_Nationality_of_Women'),
  ('Q116688847', '1933 Uruguayan coup d''état', 'José Luis Gabriel Terra Leivas (1 August 1873 – 11 September 1942) was a Uruguayan lawyer and statesman who served as the 26th constitutional president of Uruguay from 1931 to 1933 and as dictator until 1938. He led a traditionalist and corporatist regime known as the March dictatorship, because the self-coup that he led took place on 31 March 1933.', 1933, 3, 31, NULL, NULL, NULL, 'day', '31 March 1933', 26, 'https://en.wikipedia.org/wiki/1933_Uruguayan_coup_d''%C3%A9tat'),
  ('Q4569742', '1959 Uruguayan flood', 'In April 1959, severe floods hit the country of Uruguay (Spanish: Inundaciones de abril de 1959 en Uruguay) that were the most severe in the modern history of the country. Rainfall lasted from March 24 until April 23 and as a consequence, the Río Negro suffered an overtopping.', 1959, 4, NULL, NULL, NULL, NULL, 'month', 'April 1959', 37, 'https://en.wikipedia.org/wiki/1959_Uruguayan_flood'),
  ('Q389853', '1973 Uruguayan coup d''état', 'The 1973 Uruguayan coup d''état took place in Uruguay on 27 June 1973 and marked the beginning of the civic-military dictatorship which lasted until 1985. President Juan María Bordaberry closed parliament and ruled with the assistance of a junta of military generals.', 1973, 6, 27, NULL, NULL, NULL, 'day', '27 June 1973', 48, 'https://en.wikipedia.org/wiki/1973_Uruguayan_coup_d''%C3%A9tat'),
  ('Q3028762', 'Austral Líneas Aéreas Flight 2553', 'Austral Líneas Aéreas Flight 2553 was an Argentine domestic scheduled passenger flight from Posadas to Buenos Aires. On October 10, 1997, the McDonnell Douglas DC-9-32 that was operating the flight crashed on the lands of Estancia Magallanes, Nuevo Berlín, 32 kilometres (20 mi; 17 nmi) away from Fray Bentos, Uruguay.', 1997, 10, 10, NULL, NULL, NULL, 'day', '10 October 1997', 53, 'https://en.wikipedia.org/wiki/Austral_L%C3%ADneas_A%C3%A9reas_Flight_2553'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q109425781', '2022 Uruguayan Referendum on the Urgent Consideration Law', 'A referendum on the Urgent Consideration Law was held in Uruguay to ask the electorate if 135 articles of Law 19,889 (known as the "Urgent Consideration Law", "Urgency Law" or simply "LUC") – approved by the General Assembly in 2020 and considered as the main legislative initiative of the coalition government of President Luis Lacalle Pou — should be repealed. It was the result of a campaign promoted by various social and political actors such as the national trade union center PIT-CNT and the opposition party Broad Front.', 2022, 3, 27, NULL, NULL, NULL, 'day', '27 March 2022', 37, 'https://en.wikipedia.org/wiki/2022_Uruguayan_Law_of_Urgent_Consideration_referendum');
